pub const VELNOR_GEN_MARKER: &str = "# Generated by velnor-gen.";
const ENGINE_MARKERS: [&str; 2] = [
    "# Generated by Velnor Actions ",
    "# Generated by velnor-actions ",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Owner {
    VelnorGen,
    Engine,
    Nobody,
}

#[must_use]
pub fn owner_of(contents: &[u8]) -> Owner {
    let first = contents
        .split(|byte| *byte == b'\n')
        .next()
        .unwrap_or_default();
    let first = first.strip_suffix(b"\r").unwrap_or(first);
    if let Some(rest) = first.strip_prefix(VELNOR_GEN_MARKER.as_bytes())
        && (rest.is_empty() || rest.starts_with(b" "))
    {
        Owner::VelnorGen
    } else if ENGINE_MARKERS
        .iter()
        .any(|marker| first.starts_with(marker.as_bytes()))
    {
        Owner::Engine
    } else {
        Owner::Nobody
    }
}
